import sys


def main():
    data = sys.stdin.read().split()
    R, C = int(data[0]), int(data[1])
    g = [[int(data[2 + i * C + j]) for j in range(C)] for i in range(R)]
    n = R * C

    def sift(root, end):
        while True:
            child = 2 * root + 1
            if child >= end:
                return
            if child + 1 < end and g[child // C][child % C] < g[(child + 1) // C][(child + 1) % C]:
                child += 1
            ra, ca = divmod(root, C)
            rb, cb = divmod(child, C)
            if g[ra][ca] < g[rb][cb]:
                g[ra][ca], g[rb][cb] = g[rb][cb], g[ra][ca]
                root = child
            else:
                return

    for s in range(n // 2 - 1, -1, -1):
        sift(s, n)
    for e in range(n - 1, 0, -1):
        r, c = divmod(e, C)
        g[0][0], g[r][c] = g[r][c], g[0][0]
        sift(0, e)
    print('\n'.join(' '.join(map(str, row)) for row in g))


